-- Nhóm 3, Phần D (mở rộng riêng) — Bảng bài viết + đánh giá cho hệ
-- sinh thái/dự án con, dùng chung cho mọi hệ sinh thái hiện tại và tương
-- lai (6, 7, 8...). Schema generic id/data jsonb/status/order, đăng ký
-- vào SUPABASE_COLLECTIONS như mọi bảng generic khác — không viết API mới.
--
-- LƯU Ý (đã sửa sau khi apply lần đầu): field tri-state của
-- ecosystem_ratings trong `data` đặt tên "ratingStatus" (KHÔNG phải
-- "status") — cột `status` ngoài `data` là trạng thái Draft/Published
-- của route generic /api/admin/collections/[table], GET route đó merge
-- `status: row.status` ĐÈ SAU cùng lên `data`, nên nếu để trùng tên
-- "status" bên trong `data`, giá trị "not-assessed"/"met"/"not-met" sẽ bị
-- ghi đè mất bởi "Published" (xem cùng bug đã ghi trong CLAUDE.md mục
-- "Bug đã sửa: /api/admin/collections/[table] GET không trả status"). Đã
-- sửa qua execute_sql ngay sau khi phát hiện, trước khi có code nào đọc.

create table if not exists ecosystem_articles (
  id text primary key,
  data jsonb not null default '{}'::jsonb,
  status text not null default 'Draft',
  "order" int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table ecosystem_articles enable row level security;
create policy "public read published" on ecosystem_articles
  for select using (status = 'Published');

create table if not exists ecosystem_ratings (
  id text primary key,
  data jsonb not null default '{}'::jsonb,
  status text not null default 'Published',
  "order" int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table ecosystem_ratings enable row level security;
create policy "public read published" on ecosystem_ratings
  for select using (status = 'Published');

-- Seed: 60 dòng đánh giá mặc định (10 thực thể × 6 tiêu chí cố định),
-- trạng thái "chưa đánh giá" trung thực — Admin sửa dần qua Live-edit.
on conflict (id) do nothing;

-- Seed: 3 bài viết thật cho Hệ sinh thái DigiU (cấp hệ sinh thái, chưa
-- gắn dự án con nào — subProjectId rỗng).
on conflict (id) do nothing;
